        x, y = int(parts[0]), int(parts[1])
        points.append((x, y))

    # Collect all unique x and y coordinates
    x_coords = set(p[0] for p in points)
    y_coords = set(p[1] for p in points)

    # Build result: all original points + strategic additional points
    result = list(points)
    result_set = set(result)

    # Generate additional points to satisfy "good" property
    # We create a grid-like structure from the available coordinates
    # This ensures that for any two points, either they share x, share y,
    # or there's an "intersection point" in the bounding box

    for x in x_coords:
        for y in y_coords:
            pt = (x, y)
            if pt not in result_set:
                # This point can help form rectangles
                # Add it only if we're not creating too many points
                # We have a limit of 2*10^5, so we can afford some full grid
