def is_gp(arr):
    n = len(arr)
    if n <= 1:
        return True
    if all(x == 0 for x in arr):
        return True

    # For sequences starting with 0
    if arr[0] == 0:
        # All remaining must be 0 to form a GP
        return all(x == 0 for x in arr[1:])

    # Calculate common ratio from first two elements
    r = arr[1] / arr[0]

    # Check all elements satisfy the GP formula
    for i in range(2, n):
        expected = arr[0] * (r ** (i - 1))
        if abs(arr[i] - expected) > 1e-9:
            return False

    return True

def try_delete(index, arr):
    return len(arr) - 1 <= 1 or is_gp(arr[:index] + arr[index+1:])

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Output 0 if already a GP
    if is_gp(a):
        return "0\n"

    # Try deleting each element
    for i in range(len(a)):
        rest = a[:i] + a[i+1:]
        if is_gp(rest):
            return "1\n"

    return "2\n"

