from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        line = lines[i].split()
        if len(line) >= 2:
            u, v = int(line[0]), int(line[1])
            adj[u].append(v)
            adj[v].append(u)

    if m + 1 < len(lines):
        visits = list(map(int, lines[m + 1].split()))
    else:
        visits = [0] * n

    # Special cases
    if len(visited) == 0 or all(v == 0 for v in visits):
        # No odd requirements
        return "0\n"

    # Get vertices needing odd visits
    odd_visits = [i for i in range(1, n + 1) if visits[i - 1] == 1]

    # Odd count of odd-visit vertices is impossible
    if len(odd_visits) % 2 == 1:
        return "-1\n"

    path = []

    for i in range(0, len(odd_visits) - 1, 2):
        u = odd_visits[i]
        v = odd_visits[i + 1]

        # Find path using BFS
        if u == v:
            path.append(u)
        else:
            q = deque([(u, [u])])
            visited_set = {u}
            found = False
            while q and not found:
                curr, curr_path = q.popleft()
                for neighbor in adj[curr]:
                    if neighbor == v:
                        path.extend(curr_path[1:] + [v])
                        found = True
                        break
                    if neighbor not in visited_set:
                        visited_set.add(neighbor)
                        q.append((neighbor, curr_path + [neighbor]))

    path.insert(0, odd_visits[0])

    if len(path) == 0:
        return "0\n"

    output_path = " ".join(map(str, path))
    return f"{len(path)}\n{output_path}\n"

