def count_squares(matrix, n, m):
    count = 0    
    for r in range(n):
        for c in range(m):
            for s in range(2, min(n - r, m - c) + 1):
                valid = True
                # Check top and bottom rows of border
                for rr in [r, r + s - 1]:
                    for cc in range(c, c + s):
                        if matrix[rr][cc] != '1':
                            valid = False
                            break
                    if not valid:
                        break
                if not valid:
                    continue

                # Check left and right columns of border
                for cc in [c, c + s - 1]:
                    for rr in range(r + 1, r + s - 1):
                        if matrix[rr][cc] != '1':
                            valid = False
                            break
                    if not valid:
                        break
                if not valid:
                    continue

                # Interior must be all 0s
                for rr in range(r + 1, r + s - 1):
                    for cc in range(c + 1, c + s - 1):
                        if matrix[rr][cc] != '0':
                            valid = False
                            break
                    if not valid:
                        break
                if not valid:
                    continue

                # Check no foreign 1s touch the border (adjacent by side or corner)
                for rr in range(max(0, r - 1), min(n, r + s)):
                    for cc in range(max(0, c - 1), min(m, c + s)):
                        d_r, d_c = abs(rr - r), abs(cc - c)
                        on_border = (d_r == 0 and 0 <= cc < s) or (d_c == 0 and 0 <= rr < s)
                        if matrix[rr][cc] == '1' and not on_border:
                            valid = False
                            break
                    if not valid:
                        break
                if valid:
                    count += 1

                # Also check diagonal/diamond squares
                for rad in range(1, min(n - r, m - c) + 1):
                    border_cells = set()
                    for dr in range(-rad, rad + 1):
                        for dc in range(-rad, rad + 1):
                            if abs(dr) + abs(dc) == rad:
                                rr, cc = r + dr, c + dc
                                if 0 <= rr < n and 0 <= cc < m:
                                    border_cells.add((rr, cc))

                    # Check border is all 1s
                    valid = True
                    for rr, cc in border_cells:
                        if matrix[rr][cc] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Interior (distance < rad) must be 0s
                    for dr in range(-rad + 1, rad):
                        for dc in range(-rad + 1, rad):
                            if abs(dr) + abs(dc) < rad:
                                rr, cc = r + dr, c + dc
                                if 0 <= rr < n and 0 <= cc < m:
                                    if matrix[rr][cc] != '0':
                                        valid = False
                                        break
                        if not valid:
                            break

                    if not valid:
                        continue

                    # Check no foreign 1s touch the border
                    valid = True
                    for dr in range(-rad - 1, rad + 2):
                        for dc in range(-rad - 1, rad + 2):
                            if abs(dr) + abs(dc) <= rad:
                                continue
                            rr, cc = r + dr, c + dc
                            if 0 <= rr < n and 0 <= cc < m and matrix[rr][cc] == '1':
                                valid = False
                                break
                        if not valid:
                            break

                    if valid:
                        count += 1

    return count

