    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].add(v)
        adj[v].add(u)
        edges.append((u, v))

    # Use Union-Find to count connected components
    uf = UnionFind(n)
    for u, v in edges:
        uf.union(u, v)

    num_components = uf.count

    # Check for cycles using DFS
    has_cycle = False
    visited = [False] * (n + 1)

    def detect_cycle(start):
        nonlocal has_cycle
        stack = [(start, iter(adj[start]))]
        visited[start] = True
        while stack:
            node, neighbors = stack[-1]
            try:
                neighbor = next(neighbors)
                if visited[neighbor]:
                    if neighbor != adj[start].difference(
