    # Split by +/- where they appear at start of potential term
    summands = []
    i = 0
    n = len(expr)

    while i < n:
        # Find the start of this summand
        start = i
        if i > 0:
            # Find sign
            while i < n and expr[i] not in ['+', '-']:
                i += 1
        # Determine the sign
        sign = '+'
        if i < n and expr[i] == '-':
            sign = '-'
            i += 1
        elif i < n and expr[i] == '+':
            i += 1

        # Find the end of this summand (next + or - or end)
        while i < n and expr[i] not in ['+', '-']:
            i += 1

        term = expr[start:i]
        # Parse term: may have coefficient * operation
        parts = term.split('*')
        if len(parts) == 2:
            coefficient = int(parts[0])
            op_str = parts[1]
        else:
            coefficient = 1
            op_str = term

        if op_str == 'a++':
            summands.append({'sign': sign, 'coeff': coefficient, 'op': 'a++'})
        elif op_str == '++a':
            summands.append({'sign': sign, 'coeff': coefficient, 'op': '++a'})

    # Group summands by operation type
    a_plus_s = [s for s in summands if s['op'] == 'a++']
    inc_a_s = [s for s in summands if s['op'] == '++a']

    # Calculate contribution:
    # Strategy: do all ++a first (they increment a, making subsequent values higher), 
    # then do all a++ (they use higher a values)

    current_a = a
    total = 0

    # Process all ++a first
    # Each ++a increments a then returns coeff * a
    # Since all ++a are done first, and a++ ops haven't incremented yet
    # Each ++a contributes 0 to actual compute but changes a
    for s in inc_a_s:
        current_a += 1
        total += s['sign'] * s['coeff'] * current_a

    # Now process a++ (multiply current a, then increment)
    current_a = a
    for s in a_plus_s:
        total += s['sign'] * s['coeff'] * current_a
        current_a += 1

    return str(total)

