def solution(full_input):
    lines = full_input.strip().split('\n')

    # Parse first line: n m [swapLR] [swapUD]
    first_parts = lines[0].split()
    n, m = int(first_parts[0]), int(first_parts[1])
    swapLR = int(first_parts[2]) if len(first_parts) > 2 else 0
    swapUD = int(first_parts[3]) if len(first_parts) > 3 else 0

    # Parse grid (next n lines)
    grid = [list(lines[i]) for i in range(1, n + 1)]

    # Find start and target positions
    start = (0, 0)  # 0-indexed (1,1) is (0,0)
    target = None

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'F':
                target = (r, c)
                break
        if target:
            break

    # Define direction changes based on swaps
    # Without swaps: U=(-1,0), D=(1,0), L=(0,-1), R=(0,1)
    if swapLR and swapUD:
        # Both swapped: U->D, D->U, L->R, R->L (double swapped)
        dir_map = {'U': (1, 0), 'D': (-1, 0), 'L': (0, 1), 'R': (0, -1)}
    elif swapLR:
        # Only L/R swapped
        dir_map = {'U': (-1, 0), 'D': (1, 0), 'L': (0, 1), 'R': (0, -1)}
    elif swapUD:
        # Only U/D swapped
        dir_map = {'U': (1, 0), 'D': (-1, 0), 'L': (0, -1), 'R': (0, 1)}
    else:
        # No swaps
        dir_map = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}

    # BFS to find path
    queue = collections.deque()
    queue.append((start[0], start[1], ""))
    visited = set([start])

    result = ""

    while queue:
        r, c, path = queue.popleft()

        if (r, c) == target:
            result = path
            break

        for move in ['U', 'D', 'L', 'R']:
            dr, dc = dir_map[move]
            nr, nc = r + dr, c + dc

            # Check bounds
            if 0 <= nr < n and 0 <= nc < m:
                # Check if cell is safe (not *)
                if grid[nr][nc] != '*':
                    if (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc, path + move))

    return result

