        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            if size[px] < size[py]:
                px, py = py, px
            parent[py] = px
            size[px] += size[py]

    for u, v in edges:
        union(u, v)

    # Get all component sizes
    roots = set()
    for i in range(1, n + 1):
        roots.add(find(i))

